'use strict';
const bgm=document.querySelector('#music'),toggle=document.querySelector('#music-toggle'),status=document.querySelector('#media-status');
const ambients=[...document.querySelectorAll('video.ambient')];const visibility=new Map();let entered=false;const videoPlayers={};let activeVideo=null;let youtubeLoading=null;
function report(message){status.textContent=message;}
function syncMusic(){toggle.textContent=bgm.paused?'▶':'Ⅱ';toggle.setAttribute('aria-label',bgm.paused?'배경음악 재생':'배경음악 일시정지');document.querySelector('#ost-invite').textContent=bgm.paused?'♫ OST와 함께 둘러보기':'Ⅱ 배경음악 잠시 멈추기';}
function stopMV(){activeVideo=null;Object.values(videoPlayers).forEach(p=>{if(typeof p.pauseVideo==='function')p.pauseVideo();});}
bgm.volume=.35;bgm.addEventListener('play',()=>{stopMV();report('');syncMusic();});bgm.addEventListener('pause',syncMusic);bgm.addEventListener('error',()=>report('음악을 불러오지 못했습니다. 다시 시도해 주세요.'));
async function toggleMusic(){if(!bgm.paused){bgm.pause();return;}stopMV();try{await bgm.play();}catch{report('음악 재생 버튼을 다시 눌러 주세요.');}}
toggle.onclick=toggleMusic;document.querySelector('#ost-invite').onclick=toggleMusic;document.querySelector('#music-volume').oninput=e=>bgm.volume=Number(e.target.value);
document.querySelector('#music-select').onchange=async e=>{const wasPlaying=!bgm.paused;bgm.pause();bgm.src=`assets/${e.target.value}.m4a`;bgm.load();document.querySelector('#music-time').textContent='0:00';report('');if(wasPlaying)try{await bgm.play();}catch{report('재생 버튼을 눌러 주세요.');}};
bgm.addEventListener('timeupdate',()=>{const s=Math.floor(bgm.currentTime);document.querySelector('#music-time').textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;});
function refreshAmbient(){ambients.forEach(v=>{if(entered&&visibility.get(v)&&v.getClientRects().length&&!document.hidden){if(!v.src)v.src=v.dataset.src;v.play().catch(()=>{});}else v.pause();});}
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>visibility.set(e.target,e.isIntersecting));refreshAmbient();},{threshold:0});ambients.forEach(v=>{v.muted=true;v.loop=true;observer.observe(v);});document.addEventListener('visibilitychange',refreshAmbient);
document.querySelector('#enter-story').onclick=()=>{if(entered)return;entered=true;document.querySelector('#entry-film').pause();const content=document.querySelector('#site-content');content.hidden=false;content.inert=false;document.querySelector('#entry-screen').hidden=true;document.body.classList.remove('awaiting-entry');window.scrollTo(0,0);document.querySelector('main h1').setAttribute('tabindex','-1');document.querySelector('main h1').focus({preventScroll:true});bgm.play().catch(()=>report('재생 버튼을 누르면 OST가 시작됩니다.'));refreshAmbient();};
function loadYouTube(){if(window.YT?.Player)return Promise.resolve();if(youtubeLoading)return youtubeLoading;youtubeLoading=new Promise((resolve,reject)=>{window.onYouTubeIframeAPIReady=resolve;const script=document.createElement('script');script.id='yt-api';script.src='https://www.youtube.com/iframe_api';script.onerror=()=>{youtubeLoading=null;script.remove();reject(new Error('YouTube unavailable'));};document.head.append(script);});return youtubeLoading;}
async function startVideo(key){bgm.pause();activeVideo=key;Object.entries(videoPlayers).forEach(([other,p])=>{if(other!==key&&typeof p.pauseVideo==='function')p.pauseVideo();});const ids={teaser:'XgVjoJB0o2E',mv:'BOECYJ8zjm4'};const labels={teaser:'공식 티저',mv:'공식 MV'};try{await loadYouTube();if(activeVideo!==key)return;if(videoPlayers[key]){if(typeof videoPlayers[key].playVideo==='function')videoPlayers[key].playVideo();return;}document.querySelector('#'+key+'-frame').innerHTML='<div id="youtube-'+key+'"></div>';videoPlayers[key]=new YT.Player('youtube-'+key,{videoId:ids[key],host:'https://www.youtube-nocookie.com',playerVars:{playsinline:1,rel:0,origin:location.origin},events:{onReady:e=>{e.target.getIframe().title='대역의 죄 '+labels[key];if(activeVideo===key)e.target.playVideo();},onStateChange:e=>{if(e.data===1){activeVideo=key;bgm.pause();Object.entries(videoPlayers).forEach(([other,p])=>{if(other!==key&&typeof p.pauseVideo==='function')p.pauseVideo();});}else if(e.data===0&&activeVideo===key){activeVideo=null;bgm.play().catch(()=>report('영상이 끝났습니다. 재생 버튼을 누르면 BGM이 이어집니다.'));}},onError:()=>report(labels[key]+'를 재생할 수 없으면 유튜브에서 보기 링크를 이용해 주세요.')}});}catch{report('영상을 불러오지 못했습니다. 유튜브에서 보기 링크를 이용해 주세요.');}}
document.querySelector('#play-mv').onclick=()=>startVideo('mv');document.querySelector('#play-teaser').onclick=()=>startVideo('teaser');syncMusic();

document.querySelectorAll('[data-identity]').forEach(button=>button.addEventListener('click',()=>{const secret=button.dataset.identity==='secret';document.querySelectorAll('.dual-film video').forEach((video,index)=>{const selected=index===(secret?1:0);video.style.display=selected?'block':'none';video.pause();visibility.set(video,selected);if(selected)video.currentTime=0;});refreshAmbient();}));

const entryFilm=document.querySelector('#entry-film');entryFilm.muted=true;entryFilm.play().catch(()=>{});document.addEventListener('visibilitychange',()=>{if(!entered&&!document.hidden)entryFilm.play().catch(()=>{});else entryFilm.pause();});
